insert into ledger_corrections (decided_on, decided_by, subject, action, reason, buildium_detail) values ('2026-10-03', 'Stephen Henry', 'Andrew Cannon — Unit 12 lease entered in error', 'merge_lease', 'Andrew Cannon is in Unit 2. Buildium opened a lease on Unit 12 by mistake (7/1–7/7/2026, left ''Active''), took his 6/18/2026 card payments there, then ''moved'' them to Unit 2 with two manual-cash entries and charged the $1,800 deposit a second time. The Unit 12 lease is removed; his real charges and payments move to his Unit 2 lease; the two transfer entries and the duplicate deposit charge are removed.', '{"removed_lease": {"rental": "6622 North Bourbon Street #12", "tenants": "Andrew Cannon", "buildium_balance": "-205", "lines_moved": 6}, "removed_lines": [{"entry_date": "2026-07-08", "gl_account": "Rent Income", "raw_type": "Manual cash payment successful", "description": "From #12 to #2", "amount": "-205"}, {"entry_date": "2026-07-08", "gl_account": "Security Deposit Liability", "raw_type": "Manual cash payment successful", "description": "From Incorrect Lease #12 to #2", "amount": "-1800"}, {"entry_date": "2026-07-08", "gl_account": "Security Deposit Liability", "raw_type": "Charge", "description": "Security deposit", "amount": "1800"}], "into_lease": {"rental": "6626 North Bourbon Street #2", "tenants": "Andrew Cannon"}}'::jsonb);
insert into ledger_corrections (decided_on, decided_by, subject, action, reason, buildium_detail) values ('2026-10-03', 'Stephen Henry', '3446 N. 12th Street is a land contract, not a tenancy', 'land_contract', '3446 N. 12th Street is a land contract, not a tenancy. Buildium recorded it as an at-will lease with ''rent''. The buyers rented under a 2019 lease from 12/30/2019 until the land contract (dated 3/2/2020, recorded 3/5/2020), then paid installments from 4/1/2020. Imported as a land contract with its full payment history and the Exhibit A amortization schedule.', '{"buildium_lease": {"rental": "3446 North 12th Street", "tenants": "Shaudai Evans, William Marshall", "type": "At-will (month-to-month)", "rent": "599.47", "start": "2020-01-01 00:00:00", "lines": 240}}'::jsonb);
insert into ledger_corrections (decided_on, decided_by, subject, action, reason, buildium_detail) values ('2026-10-03', 'Stephen Henry', 'Ashley Williams — work in lieu of rent (Unit 4)', 'reclassify_in_kind', 'Ashley Williams is doing work in lieu of rent. Buildium entered her paint/cleaning and floor work as ordinary credits; they are in-kind payments for work done and are linked to work log entries.', '{"lines": [{"date": "2026-08-27", "description": "Paint & Cleaning", "amount": "-900.00", "work": "Paint and cleaning"}, {"date": "2026-08-27", "description": "Floor preparation", "amount": "-900.00", "work": "Floor preparation"}]}'::jsonb);
insert into ledger_corrections (decided_on, decided_by, subject, action, reason, buildium_detail) values ('2026-10-03', 'Stephen Henry', 'Tamika Moore — Unit 11 rent is $850, not $0', 'set_lease_fields', 'Buildium''s lease record shows current rent $0, but her tenant statement shows an $850 recurring rent charge every month since March 2024, paid in full. The lease''s rent is set to $850.', '{"fields": {"rent": "850.00"}, "buildium": {"rent": "0"}}'::jsonb);
insert into ledger_corrections (decided_on, decided_by, subject, action, reason, buildium_detail) values ('2026-10-03', 'Stephen Henry', 'Ashley Williams — September and October 2026 rent never posted', 'add_charges', 'Buildium never posted Ashley Williams'' September and October 2026 rent ($900 each). Her $1,800 of work credits (paint & cleaning, floor preparation) pay those two months. The charges are added so her statement is right.', '{"added_lines": [{"date": "2026-09-01", "gl": "Rent Income", "description": "Rent", "amount": "900.00"}, {"date": "2026-10-01", "gl": "Rent Income", "description": "Rent", "amount": "900.00"}]}'::jsonb);
insert into ledger_corrections (decided_on, decided_by, subject, action, reason, buildium_detail) values ('2026-10-03', 'Stephen Henry', 'James Pritchard — one-day Unit 3 lease (5/1/2025) entered in error', 'remove_lease', 'James Pritchard owes nothing. Buildium has a one-day lease for him alone on 5/1/2025 with $900 rent and an $1,800 deposit charged and a $32 application-fee credit, never paid ($2,668). His tenancy is the joint lease with Zackary Pritchard from 5/2/2025. The one-day lease and its lines are removed.', '{"removed_lease": {"rental": "6626 North Bourbon Street #3", "tenants": "James Pritchard", "buildium_balance": "2668", "lines": [{"entry_date": "2025-05-01", "gl_account": "Application Fee Income", "raw_type": "Credit", "description": "Application Fee", "amount": "-32"}, {"entry_date": "2025-05-01", "gl_account": "Rent Income", "raw_type": "Charge", "description": "Rent", "amount": "900"}, {"entry_date": "2025-05-01", "gl_account": "Security Deposit Liability", "raw_type": "Charge", "description": "Security Deposit", "amount": "1800"}]}}'::jsonb);
